import type { Metadata, MetadataRoute } from 'next';
import { connection } from 'next/server';

import { getAppUrl } from '@/lib/platform/email/app-url';
import {
  APP_NAME,
  formatDocumentTitle,
  PAGE_TITLE_TEMPLATE,
  PAGE_TITLES,
} from '@/lib/shared/document-title';

const SITE_DESCRIPTION = 'System zarządzania mieszkaniami ATU';
/** Social preview generated by src/app/opengraph-image.tsx. */
const SOCIAL_IMAGE_URL = '/opengraph-image';
/** Browser chrome colour from the app's theme tokens: primary in light mode, background in dark. */
export const THEME_COLOR = [
  { media: '(prefers-color-scheme: light)', color: '#2563eb' },
  { media: '(prefers-color-scheme: dark)', color: '#020817' },
];
const OG_LOCALE = 'pl_PL';

/** Paths a signed-out visitor can open. Only these are indexed. */
export const PUBLIC_PAGES = {
  login: {
    path: '/login',
    title: PAGE_TITLES.login,
    description:
      'Zaloguj się do ekartoteki ATU, systemu zarządzania wspólnotami mieszkaniowymi.',
  },
  register: {
    path: '/register',
    title: PAGE_TITLES.register,
    description:
      'Załóż konto w ekartotece ATU, systemie zarządzania wspólnotami mieszkaniowymi.',
  },
  forgotPassword: {
    path: '/forgot-password',
    title: PAGE_TITLES.forgotPassword,
    description: 'Odzyskaj dostęp do konta w ekartotece ATU.',
  },
  privacy: {
    path: '/privacy',
    title: PAGE_TITLES.privacy,
    description:
      'Polityka prywatności ekartoteki ATU: zasady przetwarzania danych osobowych.',
  },
} as const;

/** Sections only signed-in users reach. Crawlers are kept out of them. */
const PRIVATE_PATHS = ['/api/', '/dashboard', '/admin'];

interface PublicPage {
  path: string;
  title: string;
  description: string;
}

/** Metadata of a public page: indexable, with its own canonical URL and previews. */
export function publicPageMetadata({
  path,
  title,
  description,
}: PublicPage): Metadata {
  const fullTitle = formatDocumentTitle(title);

  return {
    title,
    description,
    alternates: { canonical: path },
    robots: { index: true, follow: true },
    openGraph: {
      type: 'website',
      siteName: APP_NAME,
      locale: OG_LOCALE,
      title: fullTitle,
      description,
      url: path,
      images: [SOCIAL_IMAGE_URL],
    },
    twitter: {
      card: 'summary_large_image',
      title: fullTitle,
      description,
      images: [SOCIAL_IMAGE_URL],
    },
  };
}

/** Site-wide metadata. Every page is private unless it opts in with publicPageMetadata. */
export async function getRootMetadata(): Promise<Metadata> {
  // APP_URL is runtime config, so it must not be frozen into the build
  await connection();

  return {
    metadataBase: new URL(getAppUrl()),
    title: {
      template: PAGE_TITLE_TEMPLATE,
      default: APP_NAME,
    },
    description: SITE_DESCRIPTION,
    robots: { index: false, follow: false },
  };
}

export async function getRobots(): Promise<MetadataRoute.Robots> {
  await connection();

  return {
    rules: { userAgent: '*', allow: '/', disallow: PRIVATE_PATHS },
    sitemap: absoluteUrl('/sitemap.xml'),
  };
}

export async function getSitemap(): Promise<MetadataRoute.Sitemap> {
  await connection();

  return Object.values(PUBLIC_PAGES).map(({ path }) => ({
    url: absoluteUrl(path),
  }));
}

function absoluteUrl(path: string): string {
  return new URL(path, getAppUrl()).toString();
}
